head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > pow]<br/>현재 bigDecimal 데이터를 입력받은 지수만큼 거듭제곱하여 결과를 반환합니다.",
    "validation" : [
        "bigDecimal(필수) 파라미터로 거듭제곱의 지수에 해당하는 bigDecimal 데이터를 설정할 수 있어야 합니다.",
        "거듭제곱 결과를 bigDecimal 타입으로 반환해야 합니다.",
        "지수의 소수점 이하는 무시되어야 합니다.",
        "피연산자가 빈 문자열에서 생성된 bigDecimal 인 경우 0 으로 대체하여 연산해야 합니다.",
        "연산 중 오류가 발생하면 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_pow_onclick = function () {
    let a = $p.bigDecimal("11111");
    let b = $p.bigDecimal("5");
    let ret = a.pow(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.pow(5) : " + ret.toString());
}



scwin.btn_powDecimal_onclick = function () {
    let a = $p.bigDecimal("11111");
    let b = $p.bigDecimal("5.7");
    let ret = a.pow(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.pow(5.7) : " + ret.toString());
}



scwin.btn_powEmpty_onclick = function () {
    let a = $p.bigDecimal("11111");
    let b = $p.bigDecimal("");
    let ret = a.pow(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.pow('') : " + ret.toString());
}



scwin.btn_powNaN_onclick = function () {
    let a = $p.bigDecimal("abc");
    let b = $p.bigDecimal("5");
    let ret = a.pow(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a('abc').pow(5) : " + ret.toString());
}
